49	/// The value an override resolves to.
50	#[derive(Debug, Clone)]
51	pub enum NpmOverrideValue {
52	  /// A version requirement, e.g. "1.0.0" or "^2.0.0".
53	  Version(VersionReq),
54	  /// An npm alias override, e.g. "npm:other-package@^1.0.0".
55	  /// Replaces the dependency with a different package.
56	  Alias {
57	    package: PackageName,
58	    version_req: VersionReq,
59	  },
60	  /// No self-override (only child overrides exist). This corresponds to the
61	  /// case where the override key maps to an object without a "." key.
62	  Inherited,
63	  /// The override was explicitly removed (empty string `""`). This cancels
64	  /// any outer override for the same package within a scoped context.
65	  Removed,
