/// Extracts the bare package name from an override key, stripping any
/// version selector (e.g. `foo@^1.0.0` → `foo`, `@scope/name@1` →
/// `@scope/name`).
fn package_name_from_key(key: &str) -> &str {
  if let Some(rest) = key.strip_prefix('@') {
    // scoped package — the name ends at the second '@' if present
    match rest.find('@') {
      Some(idx) => &key[..idx + 1],
      None => key,
    }
  } else {
    match key.find('@') {
      Some(idx) => &key[..idx],
      None => key,
    }
